module gray_counter4_fix(
    input            clk,
    input            rst_n,
    input            enable,
    output     [3:0] gray_out,
    output reg [3:0] bin_cnt
);
    // BUG: operator precedence error without parentheses
    assign gray_out = (bin_cnt >> (1 ^ bin_cnt)); // BUG!

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            bin_cnt <= 4'd0;
        else if (enable)
            bin_cnt <= bin_cnt + 4'd1;
    end
endmodule

