module edge_detector_fall_fix(
    input      clk,
    input      rst_n,
    input      sig_in,
    output reg rise_pulse,
    output reg fall_pulse
);
    reg sig_d;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sig_d <= 1'b0;
            rise_pulse <= 1'b0;
            fall_pulse <= 1'b0;
        end else begin
            sig_d <= sig_in;
            rise_pulse <= sig_in && !sig_d;
            // BUG: Duplicated rising edge logic instead of falling edge!
            fall_pulse <= sig_in && !sig_d; // BUG!
        end
    end
endmodule

