module priority_enc4_zero_fix(
    input      [3:0] in_vec,
    output reg [1:0] code_out,
    output           none_active
);
    // BUG: none_active is inverted!
    assign none_active = |in_vec; // BUG! Should be ~|in_vec

    always @(*) begin
        if (in_vec[3]) code_out = 2'b11;
        else if (in_vec[2]) code_out = 2'b10;
        else if (in_vec[1]) code_out = 2'b01;
        else code_out = 2'b00;
    end
endmodule
